import { useAudioPlayer } from "expo-audio";
import { useFocusEffect } from "expo-router";
import { useCallback } from "react";
import { Pressable, StyleSheet } from "react-native";

import { formatTonic, speakTonic } from "@/components/formatKey";
import { ThemedText } from "@/components/ThemedText";
import { transposePitch, type Pitch } from "@/core";

/**
 * Bundled samples, one per tonic, indexed by semitone above C. They ship inside the app,
 * so the Pitch sounds offline. Each is a steady note that loops seamlessly, so it can
 * sound for as long as the button is held. Generated by scripts/generate-pitch-samples.js.
 */
const SAMPLES = [
    require("@/assets/audio/pitch/00-C.wav"),
    require("@/assets/audio/pitch/01-Cs-Db.wav"),
    require("@/assets/audio/pitch/02-D.wav"),
    require("@/assets/audio/pitch/03-Ds-Eb.wav"),
    require("@/assets/audio/pitch/04-E.wav"),
    require("@/assets/audio/pitch/05-F.wav"),
    require("@/assets/audio/pitch/06-Fs-Gb.wav"),
    require("@/assets/audio/pitch/07-G.wav"),
    require("@/assets/audio/pitch/08-Gs-Ab.wav"),
    require("@/assets/audio/pitch/09-A.wav"),
    require("@/assets/audio/pitch/10-As-Bb.wav"),
    require("@/assets/audio/pitch/11-B.wav"),
];

/**
 * Sounds the Tag's Pitch, transposed by some semitones, for as long as it is held, like a
 * pitch pipe. It shows the tonic sounded and, in small text, the Transposition.
 *
 * The samples are steady notes, so every point in them sounds the same: a press plays from
 * wherever the last one paused, with nothing to rewind and nothing to wait for.
 */
export function PitchButton({ pitch: keyPitch, semitones }: { pitch: Pitch; semitones: number }) {
    const pitch = transposePitch(keyPitch, semitones);
    const player = useAudioPlayer(SAMPLES[pitch.semitone]);

    // Leaving the Tag page mid-note stops the note.
    useFocusEffect(
        useCallback(
            () => () => {
                try {
                    player.pause();
                } catch {
                    // On unmount the player may already be released, and so already silent.
                }
            },
            [player],
        ),
    );

    return (
        <Pressable
            style={({ pressed }) => [styles.button, pressed && styles.pressed]}
            onPressIn={() => {
                // Set on every press, as transposing swaps in a fresh player.
                player.loop = true;
                player.play();
            }}
            onPressOut={() => player.pause()}
            accessibilityRole="button"
            accessibilityLabel={`Pitch: ${speakTonic(pitch.tonic)}, ${describeTransposition(semitones)}`}
            accessibilityHint="Sounds the note while held"
        >
            <ThemedText style={styles.text}>
                {formatTonic(pitch.tonic)} <ThemedText style={styles.transposition}>({formatTransposition(semitones)})</ThemedText>
            </ThemedText>
        </Pressable>
    );
}

/** 0, +2 or −1, with a true minus sign. */
function formatTransposition(semitones: number): string {
    if (semitones > 0) return `+${semitones}`;
    if (semitones < 0) return `−${-semitones}`;
    return "0";
}

function describeTransposition(semitones: number): string {
    if (semitones === 0) return "in the Tag's Key";
    const count = Math.abs(semitones);
    return `${semitones > 0 ? "up" : "down"} ${count} semitone${count === 1 ? "" : "s"}`;
}

const styles = StyleSheet.create({
    button: {
        minWidth: 80,
        alignItems: "center",
        justifyContent: "center",
        paddingHorizontal: 12,
    },
    pressed: {
        opacity: 0.7,
    },
    text: {
        color: "#fff",
        fontWeight: "600",
        userSelect: "none",
    },
    transposition: {
        color: "#fff",
        fontSize: 12,
        fontWeight: "400",
    },
});
